package com.coraline.tycoon;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.levelgen.Heightmap;
import net.minecraft.world.item.*;

/** Incremental safe-site search and physical, resumable inspection routes. */
public final class TycoonAgency {
    public static BlockPos arrival(ServerPlayer p,TycoonData.Home h){if(h.entrance()==null)return null;var l=p.server.overworld();for(int radius:new int[]{8,12,16})for(var dir:Direction.Plane.HORIZONTAL){var at=TycoonWorld.landing(l,h.entrance().relative(dir,radius));if(at==null)continue;boolean visible=false;for(var viewer:p.server.getPlayerList().getPlayers())if(viewer.serverLevel()==l&&viewer.distanceToSqr(at.getCenter())<128*128&&viewer.getLookAngle().dot(at.getCenter().subtract(viewer.getEyePosition()).normalize())>0&&l.clip(new net.minecraft.world.level.ClipContext(viewer.getEyePosition(),at.getCenter(),net.minecraft.world.level.ClipContext.Block.COLLIDER,net.minecraft.world.level.ClipContext.Fluid.NONE,viewer)).getType()==net.minecraft.world.phys.HitResult.Type.MISS){visible=true;break;}if(!visible)return at;}return null;}
    public static void contact(ServerPlayer p){if(p.serverLevel()!=p.server.overworld())return;var h=TycoonWorld.home(p);if(!h.active())return;if(!h.state.contains("Agency")){h.state.putBoolean("AgencySearch",true);if(!h.state.contains("AgencySearchOrigin"))h.state.putLong("AgencySearchOrigin",p.blockPosition().asLong());TycoonWorld.message(p,"Contacting the agency. Surveying safe natural ground nearby; no builds will be overwritten.");}else TycoonWorld.message(p,"Agency: "+BlockPos.of(h.state.getLong("Agency")).toShortString());TycoonWorld.dirty(p);}
    private static boolean natural(net.minecraft.world.level.block.state.BlockState s){return s.is(Blocks.GRASS_BLOCK)||s.is(Blocks.DIRT)||s.is(Blocks.COARSE_DIRT)||s.is(Blocks.PODZOL);}
    public static boolean clearSite(ServerLevel l,BlockPos c){
        for(int x=-9;x<=9;x++)for(int z=-8;z<=8;z++){var at=c.offset(x,0,z);if(!l.getWorldBorder().isWithinBounds(at))return false;l.getChunkAt(at);if(!natural(l.getBlockState(at.below()))||!l.getBlockState(at.below(2)).isSolidRender(l,at.below(2)))return false;for(int y=0;y<=7;y++){var cell=at.above(y);var s=l.getBlockState(cell);if(l.getBlockEntity(cell)!=null||!s.getFluidState().isEmpty()||!(s.isAir()||s.is(Blocks.GRASS)||s.is(Blocks.TALL_GRASS)))return false;}}
        // Vanilla structure starts and POIs protect villages/landmarks in addition
        // to the strict footprint test; no carving, tree removal or road replacement.
        for(int x=-16;x<=16;x+=16)for(int z=-16;z<=16;z+=16)if(!l.getChunkAt(c.offset(x,0,z)).getAllStarts().isEmpty())return false;
        for(var family:com.coraline.parents.FamilyData.get(l.getServer()).families.values())if(family.bed!=null&&family.bed.distSqr(c)<96*96)return false;
        for(var home:TycoonData.get(l.getServer()).homes.values())if(home.entrance()!=null&&home.entrance().distSqr(c)<48*48||home.state.contains("Agency")&&BlockPos.of(home.state.getLong("Agency")).distSqr(c)<64*64)return false;
        return true;
    }
    private record Cell(BlockPos at,net.minecraft.world.level.block.state.BlockState state){}
    private static List<Cell> building(BlockPos c){var map=new LinkedHashMap<BlockPos,net.minecraft.world.level.block.state.BlockState>();
        for(int x=-7;x<=7;x++)for(int z=-6;z<=6;z++){map.put(c.offset(x,-1,z),Blocks.STONE_BRICKS.defaultBlockState());map.put(c.offset(x,0,z),Blocks.SPRUCE_PLANKS.defaultBlockState());map.put(c.offset(x,5,z),Blocks.DARK_OAK_PLANKS.defaultBlockState());for(int y=1;y<=4;y++)if(Math.abs(x)==7||Math.abs(z)==6){var b=y>=2&&y<=3&&((Math.abs(x)%4==0)||(Math.abs(z)%4==0))?Blocks.GLASS_PANE:Blocks.BRICKS;map.put(c.offset(x,y,z),b.defaultBlockState());}}
        for(int y=1;y<=4;y++)for(int z=-5;z<=5;z++)if(z!=0&&z!=1)map.put(c.offset(2,y,z),Blocks.OAK_PLANKS.defaultBlockState());
        for(int x=-5;x<=-1;x++)map.put(c.offset(x,1,-2),Blocks.SPRUCE_FENCE.defaultBlockState());
        for(int x:new int[]{-5,-3,-1})map.put(c.offset(x,1,3),Blocks.SPRUCE_STAIRS.defaultBlockState());
        for(int z:new int[]{-4,0,4}){map.put(c.offset(5,1,z),Blocks.BOOKSHELF.defaultBlockState());map.put(c.offset(6,1,z),Blocks.BARREL.defaultBlockState());}
        map.put(c.offset(-5,1,-4),Blocks.LECTERN.defaultBlockState());map.put(c.offset(-6,2,-5),Blocks.OAK_WALL_SIGN.defaultBlockState());
        for(int x:new int[]{-5,0,5})for(int z:new int[]{-4,4})map.put(c.offset(x,4,z),Blocks.LANTERN.defaultBlockState());
        for(int z:new int[]{2,4}){map.put(c.offset(4,1,z),Blocks.RED_BED.defaultBlockState());map.put(c.offset(4,1,z-1),Blocks.RED_BED.defaultBlockState().setValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.BED_PART,net.minecraft.world.level.block.state.properties.BedPart.HEAD));}
        var entrance=c.offset(-3,1,6);map.put(entrance,Blocks.OAK_DOOR.defaultBlockState());map.put(entrance.above(),Blocks.OAK_DOOR.defaultBlockState().setValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.DOUBLE_BLOCK_HALF,net.minecraft.world.level.block.state.properties.DoubleBlockHalf.UPPER));
        return map.entrySet().stream().map(e->new Cell(e.getKey(),e.getValue())).toList();
    }
    public static void tick(ServerPlayer p){var h=TycoonWorld.home(p);var n=h.state;var l=p.server.overworld();
        if(n.getBoolean("AgencySearch")){int index=n.getInt("AgencySearchIndex");if(index>=192){n.remove("AgencySearch");TycoonWorld.message(p,"No safe agency site found. Use the phone from a flatter natural area to resume the search; nothing overwritten.");n.remove("AgencySearchOrigin");n.putInt("AgencySearchIndex",0);return;}var origin=BlockPos.of(n.getLong("AgencySearchOrigin"));double angle=index*2.399963;int radius=64+(index/16)*24;int x=origin.getX()+(int)(Math.cos(angle)*radius),z=origin.getZ()+(int)(Math.sin(angle)*radius);l.getChunk(x>>4,z>>4);var c=new BlockPos(x,l.getHeight(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,x,z),z);n.putInt("AgencySearchIndex",index+1);if(clearSite(l,c)){n.putLong("Agency",c.asLong());n.putBoolean("AgencyBuilding",true);n.remove("AgencySearch");TycoonWorld.message(p,"Agency site approved: "+c.toShortString()+". Construction begins.");}TycoonWorld.dirty(p);}
        if(n.getBoolean("AgencyBuilding")){var plan=building(BlockPos.of(n.getLong("Agency")));int cursor=n.getInt("AgencyBuildCursor");for(int limit=0;limit<32&&cursor<plan.size();limit++,cursor++){var cell=plan.get(cursor);l.getChunkAt(cell.at);var old=l.getBlockState(cell.at);if(old.equals(cell.state))continue;if(!(old.isAir()||natural(old)||old.is(Blocks.GRASS)||old.is(Blocks.TALL_GRASS))){n.putString("AgencyBlocker","Construction stopped at changed footprint "+cell.at.toShortString());TycoonWorld.dirty(p);return;}l.setBlock(cell.at,cell.state,2);}n.putInt("AgencyBuildCursor",cursor);if(cursor>=plan.size()){n.remove("AgencyBuilding");n.putBoolean("AgencyBuilt",true);TycoonWorld.message(p,"The agency is open. Visit reception or request an inspection by phone.");}TycoonWorld.dirty(p);}
        if(n.getBoolean("AgencyBuilt"))clerk(p);
        if(n.getBoolean("InspectionRequested")||(n.getBoolean("EverApproved")||n.getBoolean("Approved"))&&h.clock()>=n.getLong("NextInspection"))inspection(p);
    }
    public static void clerk(ServerPlayer p){var h=TycoonWorld.home(p);var l=p.server.overworld();var at=BlockPos.of(h.state.getLong("Agency")).offset(-4,1,-3);if(!l.hasChunkAt(at))return;if(h.state.hasUUID("Clerk"))return;var actor=TycoonContent.NPC.get().create(l);if(actor==null)return;actor.configure(h.owner,UUID.randomUUID(),true,17);actor.setPos(at.getCenter().add(0,-.5,0));if(l.addFreshEntity(actor)){h.state.putUUID("Clerk",actor.getUUID());TycoonWorld.dirty(p);}}
    public static void request(ServerPlayer p){var h=TycoonWorld.home(p);if(!h.state.getBoolean("AgencyBuilt")||h.entrance()==null){TycoonWorld.message(p,"Wait for the agency to open and place your Special Door first.");return;}if(h.state.getBoolean("InspectionRequested")||h.state.hasUUID("Inspector")){TycoonWorld.message(p,"An inspection or departure is already in progress.");return;}h.state.putBoolean("InspectionRequested",true);h.state.putBoolean("Approved",false);h.state.remove("InspectionRoute");h.state.putInt("InspectionNode",0);h.state.putLong("InspectionStart",h.clock());TycoonWorld.dirty(p);TycoonWorld.message(p,"An inspector is coming to your registered entrance. Keep a clear path inside.");}
    private static void inspection(ServerPlayer p){var h=TycoonWorld.home(p);var n=h.state;if(h.entrance()==null)return;var l=p.server.overworld();var survey=TycoonRooms.survey(p);TycoonNpc agent=null;if(n.hasUUID("Inspector")){if(n.contains("InspectorAt"))l.getChunkAt(BlockPos.of(n.getLong("InspectorAt")));var e=l.getEntity(n.getUUID("Inspector"));if(e instanceof TycoonNpc npc){agent=npc;n.putLong("InspectorAt",agent.blockPosition().asLong());if(agent.getPersistentData().getBoolean("Leaving"))return;}else return;}
        if(agent==null){var at=arrival(p,h);if(at==null){n.putString("InspectionReport","Waiting for an unobtrusive safe approach outside the entrance. Clear a path and look back inside.");return;}agent=TycoonContent.NPC.get().create(l);agent.configure(h.owner,UUID.randomUUID(),true,29);agent.setPos(at.getX()+.5,at.getY(),at.getZ()+.5);agent.getPersistentData().putBoolean("Inspector",true);if(!l.addFreshEntity(agent))return;n.putUUID("Inspector",agent.getUUID());n.putLong("InspectorAt",at.asLong());n.putLong("InspectionStart",h.clock());}
        if(!n.contains("InspectionRoute")){var route=new ArrayList<BlockPos>();var enter=TycoonWorld.landing(l,h.entrance());if(enter!=null)route.add(enter);for(String id:List.of("orphan_bed","orphan_fridge","water_station","orphan_food_table"))for(var object:survey.furniture().getOrDefault(id,List.of())){var at=TycoonRooms.approach(survey.reachable(),object);if(at!=null)route.add(at);}n.putLongArray("InspectionRoute",route.stream().mapToLong(BlockPos::asLong).toArray());}
        var route=n.getLongArray("InspectionRoute");int index=n.getInt("InspectionNode");if(index<route.length){var at=BlockPos.of(route[index]);if(TycoonCare.move(agent,at,.8)){agent.gesture(2,30);n.putInt("InspectionNode",index+1);n.putLong("InspectionStart",h.clock());}else{if(Boolean.getBoolean("coraline.tycoonPhaseOneCheck")&&h.clock()%100==0){var path=agent.getNavigation().getPath();com.mojang.logging.LogUtils.getLogger().info("TYCOON_INSPECT_ROUTE node={} from={} to={} reachable={} done={} noAI={}",index,agent.position(),at,path!=null&&path.canReach(),agent.getNavigation().isDone(),agent.isNoAi());}if(h.clock()-n.getLong("InspectionStart")>1200){finish(p,survey,"Inspection could not reach a facility. Clear doors/stairs and request again.",false);agent.getPersistentData().putBoolean("Leaving",true);}}return;}
        boolean severe=h.residents.values().stream().filter(TycoonData.Resident::active).anyMatch(r->r.need("Neglect")>=TycoonConfig.SEVERE.get()||r.need("Hunger")<8||r.need("Thirst")<8);
        String report=survey.approved()?"Approved: reachable beds, dining, stocked fridge, water and safe rooms.":String.join(" ",survey.problems());finish(p,survey,report,survey.approved()&&!severe);if(severe){for(var child:h.residents.values())if(child.active())TycoonCare.depart(p,child,"AGENCY_CUSTODY");n.putLong("SuspendedUntil",h.clock()+48000);h.reputation(-25);TycoonWorld.message(p,"Severe welfare concerns: the agency is returning all placements to custody.");}agent.getPersistentData().putBoolean("Leaving",true);
    }
    public static void finish(ServerPlayer p,TycoonRooms.Survey survey,String report,boolean pass){
        var h=TycoonWorld.home(p);var n=h.state;n.remove("InspectionRequested");n.remove("InspectionRoute");n.putInt("InspectionNode",0);n.putBoolean("Approved",pass);n.putString("InspectionReport",report);h.reputation(pass?5:-5);
        if(pass){n.putBoolean("EverApproved",true);n.remove("WarningDeadline");h.milestone("first_inspection",50);}else n.putLong("WarningDeadline",h.clock()+24000);
        // A warning never removes the household from the recurring inspection roster.
        // Reputation changes frequency; failed homes receive a next-day follow-up.
        long interval=pass?Math.max(48000,TycoonConfig.INSPECTION_TICKS.get()+(h.reputation()-50)*240L)+Math.floorMod(h.owner.hashCode()+(int)(h.clock()/24000),12000):24000;
        n.putLong("NextInspection",h.clock()+interval);TycoonWorld.message(p,report);TycoonWorld.dirty(p);
    }
    public static List<TycoonData.Resident> candidates(TycoonData.Home h){var list=new ArrayList<TycoonData.Resident>();var pool=h.state.getCompound("Candidates");if(pool.isEmpty()){for(int i=0;i<3;i++){var id=UUID.randomUUID();var r=TycoonCare.generate(id);pool.put(id.toString(),r.save());}h.state.put("Candidates",pool);}for(String id:pool.getAllKeys())list.add(new TycoonData.Resident(UUID.fromString(id),pool.getCompound(id)));return list;}
    public static int fee(TycoonData.Home h){return h.reputation()<30?10:h.reputation()>75?4:6;}
    static String placeSupplied(ServerPlayer p,UUID id){
        var h=TycoonWorld.home(p);if(TycoonWorkers.contextWorker(p)==null||!TycoonPolicies.allowed(h,"placements")||!h.state.getBoolean("Approved")||h.clock()<h.state.getLong("SuspendedUntil")||h.cooldown()>0||h.activeResidents()>=TycoonPolicies.number(h,"maxResidents"))return "Agency approval, policy, capacity or cooldown prevents placement.";
        var survey=TycoonRooms.survey(p);if(!survey.approved())return "Household facilities do not pass inspection.";var bed=survey.beds().stream().filter(b->h.residents.values().stream().noneMatch(r->r.active()&&b.equals(r.bed()))).findFirst().orElse(null);var chosen=candidates(h).stream().filter(r->r.id.equals(id)).findFirst().orElse(null);if(bed==null||chosen==null||h.residents.containsKey(id))return "No safe unoccupied bed or candidate.";var arrival=arrival(p,h);return arrival==null?"Waiting for a safe unobtrusive arrival.":TycoonPlacements.commitSupplied(p,chosen,bed,arrival,fee(h));
    }
    public static String place(ServerPlayer p,UUID id){var h=TycoonWorld.home(p);if(p.serverLevel()!=p.server.overworld()||!h.state.getBoolean("Approved")||h.clock()<h.state.getLong("SuspendedUntil"))return "A current physical inspection approval is required.";if(h.cooldown()>0)return "Next placement in "+h.cooldown()/1200+" active minutes.";var survey=TycoonRooms.survey(p);if(!survey.approved())return String.join(" ",survey.problems());var beds=survey.beds().stream().filter(b->h.residents.values().stream().noneMatch(r->r.active()&&b.equals(r.bed()))).toList();if(beds.isEmpty())return "No unoccupied approved bed.";var chosen=candidates(h).stream().filter(r->r.id.equals(id)).findFirst().orElse(null);if(chosen==null||h.residents.containsKey(id))return "Placement is no longer available.";if(!TycoonShop.has(p,Items.EMERALD,fee(h)))return "Placement fee: "+fee(h)+" emeralds.";var at=arrival(p,h);if(at==null)return "Clear a safe approach outside the entrance and look inside; the arriving resident will not appear in front of you.";
        return TycoonPlacements.commit(p,chosen,beds.get(0),at,fee(h));
    }
}
